//! Integration tests against the public API only.
//!
//! These exercise the crate the way a downstream consumer would: build a
//! configuration, feed it prices and balances, and check the routing decision.
//! The wire-level behavior lives in `ladder_proxy.rs`.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use llm_ladder_router::{
    Config, CreditState, Error, ModelPrices, Offer, PriceTable, SkipReason, select,
};

const CONFIG: &str = r#"
[providers.surplus]
kind = "surplus"
base_url = "https://api.surplusintelligence.ai"
api_key_env = "SURPLUS_API_KEY"
max_cost_per_1m = 0.50

[providers.openrouter]
kind = "open_router"
base_url = "https://openrouter.ai/api/v1"
api_key_env = "OPENROUTER_API_KEY"

[[ladders]]
name = "flash"

  [[ladders.rungs]]
  provider = "surplus"
  model = "deepseek-v4-flash"
  max_cost_per_1m = 0.15

  [[ladders.rungs]]
  provider = "openrouter"
  model = "deepseek/deepseek-v4-flash"
  max_cost_per_1m = 0.30
"#;

fn offer(name: &str, completion_per_1m: f64) -> Offer {
    Offer {
        provider: name.to_string(),
        tag: None,
        prompt_per_1m: completion_per_1m / 2.0,
        completion_per_1m,
        direct_completion_per_1m: Some(0.1652),
        usable: true,
    }
}

fn funded() -> CreditState {
    let mut credits = CreditState::new();
    credits.set_balance("surplus", 74.67);
    credits.set_balance("openrouter", 12.0);
    credits
}

#[test]
fn a_ladder_takes_the_only_rung_it_can_price() {
    let config = Config::parse(CONFIG).unwrap();
    let ladder = config.ladder("flash").unwrap();

    let mut prices = PriceTable::new();
    prices.insert(
        "surplus",
        "deepseek-v4-flash",
        ModelPrices::new(vec![offer("Z.ai", 0.108)]),
    );

    let chosen = select(&config, ladder, &prices, &funded(), &[])
        .chosen
        .unwrap();
    assert_eq!(chosen.provider, "surplus");
    assert_eq!(chosen.rung, 0);
}

#[test]
fn a_priced_out_rung_leaves_the_backstop_to_serve() {
    let config = Config::parse(CONFIG).unwrap();
    let ladder = config.ladder("flash").unwrap();

    let mut prices = PriceTable::new();
    // Above the 0.15 ceiling.
    prices.insert(
        "surplus",
        "deepseek-v4-flash",
        ModelPrices::new(vec![offer("Z.ai", 0.40)]),
    );
    prices.insert(
        "openrouter",
        "deepseek/deepseek-v4-flash",
        ModelPrices::new(vec![offer("DeepInfra", 0.1372)]),
    );

    let selection = select(&config, ladder, &prices, &funded(), &[]);
    assert_eq!(selection.chosen.unwrap().provider, "openrouter");
    assert!(matches!(
        selection.skipped[0].reason,
        SkipReason::NoSellerUnderCap { .. }
    ));
}

#[test]
fn the_provider_ceiling_binds_a_rung_that_asked_for_more() {
    let config = Config::parse(
        r#"
        [providers.surplus]
        kind = "surplus"
        base_url = "https://api.surplusintelligence.ai"
        api_key_env = "SURPLUS_API_KEY"
        max_cost_per_1m = 0.20

        [[ladders]]
        name = "only"
          [[ladders.rungs]]
          provider = "surplus"
          model = "glm-5.2"
          max_cost_per_1m = 5.00
        "#,
    )
    .unwrap();
    let ladder = config.ladder("only").unwrap();

    // The rung asked for 5.00 but the provider caps everything at 0.20.
    assert_eq!(config.cap_for(ladder, &ladder.rungs[0]), Some(0.20));

    let mut prices = PriceTable::new();
    prices.insert(
        "surplus",
        "glm-5.2",
        ModelPrices::new(vec![offer("Z.ai", 0.90)]),
    );

    let selection = select(&config, ladder, &prices, &funded(), &[]);
    assert!(
        selection.chosen.is_none(),
        "0.90 is above the provider ceiling of 0.20"
    );
}

#[test]
fn an_unknown_ladder_is_not_found() {
    let config = Config::parse(CONFIG).unwrap();
    assert!(config.ladder("nonexistent").is_none());
}

#[test]
fn an_invalid_configuration_is_rejected_with_a_specific_error() {
    let error = Config::parse(
        r#"
        [providers.openrouter]
        kind = "open_router"
        base_url = "https://openrouter.ai/api/v1"
        api_key_env = "OPENROUTER_API_KEY"

        [[ladders]]
        name = "broken"
          [[ladders.rungs]]
          provider = "missing"
          model = "m"
        "#,
    )
    .unwrap_err();
    assert!(matches!(error, Error::UnknownProvider { .. }));
}

/// The value rule, exercised the way a consumer would: a multiplier is what
/// lets a dearer rung win, and it stops mattering past the premium it names.
#[test]
fn a_multiplier_decides_between_two_affordable_rungs() {
    let config = Config::parse(
        r#"
        [providers.surplus]
        kind = "surplus"
        base_url = "https://api.surplusintelligence.ai"
        api_key_env = "SURPLUS_API_KEY"

        [[ladders]]
        name = "reasoning"

          [[ladders.rungs]]
          provider = "surplus"
          model = "deepseek-v4-pro"
          max_cost_per_1m = 0.50
          score_multiplier = 2.0

          [[ladders.rungs]]
          provider = "surplus"
          model = "deepseek-v4-flash"
          max_cost_per_1m = 0.50
        "#,
    )
    .unwrap();
    let ladder = config.ladder("reasoning").unwrap();

    let chosen = select(&config, ladder, &priced(0.18, 0.10), &funded(), &[])
        .chosen
        .unwrap();
    assert_eq!(chosen.model, "deepseek-v4-pro", "0.09 beats 0.10");

    let chosen = select(&config, ladder, &priced(0.22, 0.10), &funded(), &[])
        .chosen
        .unwrap();
    assert_eq!(chosen.model, "deepseek-v4-flash", "0.11 loses to 0.10");
}

fn priced(pro: f64, flash: f64) -> PriceTable {
    let mut table = PriceTable::new();
    for (model, price) in [("deepseek-v4-pro", pro), ("deepseek-v4-flash", flash)] {
        table.insert(
            "surplus",
            model,
            ModelPrices::new(vec![Offer {
                provider: "seller".to_string(),
                tag: None,
                prompt_per_1m: price / 2.0,
                completion_per_1m: price,
                direct_completion_per_1m: Some(3.74),
                usable: true,
            }]),
        );
    }
    table
}

# Implementation plans

Plans turn an accepted specification into a reviewable sequence of small,
verifiable changes. They explain how to build the behavior; the linked
specification remains the source of truth for what the behavior must be.

Use the same kebab-case stem as the specification. A useful plan includes:

- a link to the accepted specification;
- the goal, non-goals, and assumptions relevant to implementation;
- ordered tasks with exact file paths;
- a failing test before each behavior change;
- the minimal implementation needed to pass that test;
- documentation and public-export updates;
- focused and full verification commands;
- a completion checklist updated as tasks land.

Prefer tasks that can be implemented and reviewed independently. Include short
code snippets when they remove ambiguity, but do not paste entire future files
into the plan.

See [`example-retry-policy.md`](example-retry-policy.md) for a test-first sample.

//! Unit tests for the normalized price table.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::*;
use crate::config::CostBasis;

fn offer(provider: &str, prompt: f64, completion: f64) -> Offer {
    Offer {
        provider: provider.to_string(),
        tag: None,
        prompt_per_1m: prompt,
        completion_per_1m: completion,
        direct_completion_per_1m: Some(3.74),
        usable: true,
    }
}

#[test]
fn the_cost_basis_selects_which_price_is_compared() {
    let offer = offer("Z.ai", 0.10, 0.30);

    assert!((offer.price(CostBasis::Prompt) - 0.10).abs() < f64::EPSILON);
    assert!((offer.price(CostBasis::Completion) - 0.30).abs() < f64::EPSILON);
    assert!((offer.price(CostBasis::Blended) - 0.20).abs() < f64::EPSILON);
}

#[test]
fn an_offer_at_exactly_the_ceiling_fits() {
    let offer = offer("Z.ai", 0.10, 0.30);
    // The ceiling is a maximum, not an exclusive bound.
    assert!(offer.fits(Some(0.30), CostBasis::Completion));
    assert!(!offer.fits(Some(0.29), CostBasis::Completion));
}

#[test]
fn an_uncapped_rung_admits_every_usable_offer() {
    let offer = offer("Z.ai", 100.0, 900.0);
    assert!(offer.fits(None, CostBasis::Completion));
}

#[test]
fn an_unusable_offer_fits_nothing() {
    let mut offer = offer("Z.ai", 0.001, 0.001);
    offer.usable = false;
    assert!(!offer.fits(None, CostBasis::Completion));
    assert!(!offer.fits(Some(100.0), CostBasis::Completion));
}

#[test]
fn admitted_offers_come_back_cheapest_first() {
    let prices = ModelPrices::new(vec![
        offer("dear", 0.5, 0.90),
        offer("cheap", 0.05, 0.09),
        offer("middle", 0.2, 0.30),
    ]);

    let admitted = prices.admitted(Some(0.50), CostBasis::Completion);
    assert_eq!(
        admitted
            .iter()
            .map(|offer| offer.provider.as_str())
            .collect::<Vec<_>>(),
        vec!["cheap", "middle"]
    );
}

#[test]
fn the_floor_is_the_cheapest_usable_offer_whatever_the_ceiling() {
    let mut unusable = offer("free-but-down", 0.0, 0.0);
    unusable.usable = false;
    let prices = ModelPrices::new(vec![
        unusable,
        offer("dear", 0.5, 0.90),
        offer("less", 0.3, 0.63),
    ]);

    // The floor explains a skipped rung, so it ignores the ceiling but not
    // whether the seller can actually serve.
    assert_eq!(prices.floor(CostBasis::Completion), Some(0.63));
}

#[test]
fn the_floor_is_absent_when_no_offer_is_usable() {
    let mut down = offer("down", 0.1, 0.1);
    down.usable = false;
    assert_eq!(
        ModelPrices::new(vec![down]).floor(CostBasis::Completion),
        None
    );
}

#[test]
fn a_ceiling_becomes_the_discount_that_matches_it() {
    let prices = ModelPrices::new(vec![offer("Z.ai", 0.05, 0.09)]);

    // 0.30 against a 3.74 direct price leaves 8.02%, so 91% must be discounted.
    assert_eq!(prices.discount_floor_pct(0.30), Some(91));
    // A ceiling at the direct price needs no discount at all.
    assert_eq!(prices.discount_floor_pct(3.74), Some(0));
    // A ceiling above the direct price still needs none.
    assert_eq!(prices.discount_floor_pct(99.0), Some(0));
}

#[test]
fn there_is_no_discount_to_compute_without_a_direct_price() {
    let mut offer = offer("Z.ai", 0.05, 0.09);
    offer.direct_completion_per_1m = None;
    let prices = ModelPrices::new(vec![offer]);

    // OpenRouter publishes no direct price, and guessing one would be wrong.
    assert_eq!(prices.discount_floor_pct(0.30), None);
}

#[test]
fn a_fresh_snapshot_is_not_stale() {
    let prices = ModelPrices::new(vec![offer("Z.ai", 0.1, 0.1)]);
    assert!(!prices.is_stale(std::time::Duration::from_secs(60)));
    std::thread::sleep(std::time::Duration::from_millis(2));
    assert!(prices.is_stale(std::time::Duration::ZERO));
}

#[test]
fn the_table_holds_one_entry_per_provider_and_model() {
    let mut table = PriceTable::new();
    assert!(table.is_empty());

    table.insert(
        "surplus",
        "glm-5.2",
        ModelPrices::new(vec![offer("a", 0.1, 0.1)]),
    );
    table.insert(
        "openrouter",
        "glm-5.2",
        ModelPrices::new(vec![offer("b", 0.2, 0.2)]),
    );

    assert_eq!(table.len(), 2);
    // Same model, different provider: these must not collide.
    assert_eq!(
        table.get("surplus", "glm-5.2").unwrap().offers[0].provider,
        "a"
    );
    assert_eq!(
        table.get("openrouter", "glm-5.2").unwrap().offers[0].provider,
        "b"
    );
    assert!(table.get("surplus", "absent").is_none());
    assert!(table.get("absent", "glm-5.2").is_none());
}

#[test]
fn inserting_the_same_key_replaces_the_snapshot() {
    let mut table = PriceTable::new();
    table.insert(
        "surplus",
        "glm-5.2",
        ModelPrices::new(vec![offer("old", 0.1, 0.1)]),
    );
    table.insert(
        "surplus",
        "glm-5.2",
        ModelPrices::new(vec![offer("new", 0.2, 0.2)]),
    );

    assert_eq!(table.len(), 1);
    assert_eq!(
        table.get("surplus", "glm-5.2").unwrap().offers[0].provider,
        "new"
    );
}

//! Normalized price data.
//!
//! `OpenRouter` quotes USD per token and Surplus quotes micro-USD per million
//! tokens. Both are converted to USD per million tokens at the edge so nothing
//! downstream has to remember which marketplace a number came from.

use std::time::Instant;

use crate::config::CostBasis;

/// One sub-provider's offer to serve a model.
#[derive(Debug, Clone, PartialEq)]
pub struct Offer {
    /// The sub-provider's name, as the marketplace reports it.
    pub provider: String,
    /// The slug used to steer traffic to this sub-provider, when the
    /// marketplace supports steering.
    pub tag: Option<String>,
    /// Input price, USD per million tokens.
    pub prompt_per_1m: f64,
    /// Output price, USD per million tokens.
    pub completion_per_1m: f64,
    /// The undiscounted output price this offer is quoted against, USD per
    /// million tokens, when the marketplace publishes one.
    ///
    /// Surplus expresses a ceiling as a discount off this number rather than as
    /// an absolute price, so the ratio is what the router needs.
    pub direct_completion_per_1m: Option<f64>,
    /// Whether the marketplace currently considers this offer usable.
    pub usable: bool,
}

impl Offer {
    /// The price this offer should be judged on, USD per million tokens.
    #[must_use]
    pub fn price(&self, basis: CostBasis) -> f64 {
        match basis {
            CostBasis::Completion => self.completion_per_1m,
            CostBasis::Prompt => self.prompt_per_1m,
            CostBasis::Blended => self.prompt_per_1m.midpoint(self.completion_per_1m),
        }
    }

    /// Whether this offer fits under a ceiling in USD per million tokens.
    ///
    /// An unusable offer never fits, and a rung with no ceiling admits every
    /// usable offer.
    #[must_use]
    pub fn fits(&self, cap: Option<f64>, basis: CostBasis) -> bool {
        self.usable && cap.is_none_or(|cap| self.price(basis) <= cap)
    }
}

/// Every offer for one model on one provider, as of one moment.
#[derive(Debug, Clone)]
pub struct ModelPrices {
    /// The offers, in the order the marketplace returned them.
    pub offers: Vec<Offer>,
    /// When this snapshot was taken, for staleness checks.
    pub fetched_at: Instant,
}

impl ModelPrices {
    /// Builds a snapshot taken now.
    #[must_use]
    pub fn new(offers: Vec<Offer>) -> Self {
        Self {
            offers,
            fetched_at: Instant::now(),
        }
    }

    /// Whether this snapshot is older than the configured tolerance.
    #[must_use]
    pub fn is_stale(&self, stale_after: std::time::Duration) -> bool {
        self.fetched_at.elapsed() > stale_after
    }

    /// The offers that fit under a ceiling, cheapest first.
    #[must_use]
    pub fn admitted(&self, cap: Option<f64>, basis: CostBasis) -> Vec<&Offer> {
        let mut admitted: Vec<&Offer> = self
            .offers
            .iter()
            .filter(|offer| offer.fits(cap, basis))
            .collect();
        admitted.sort_by(|left, right| {
            left.price(basis)
                .partial_cmp(&right.price(basis))
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        admitted
    }

    /// The slug that steers traffic to a named sub-provider, if it is still
    /// admitted under `cap`.
    ///
    /// A marketplace names the sub-provider that served in one vocabulary and
    /// accepts steering in another — `OpenRouter` reports "`DigitalOcean`" but
    /// routes on "digitalocean", and a quantized endpoint answers to
    /// "deepinfra/fp8". Matching case- and space-insensitively against both the
    /// display name and the slug is what lets a session return to the
    /// sub-provider holding its warm cache.
    #[must_use]
    pub fn steering_slug(&self, name: &str, cap: Option<f64>, basis: CostBasis) -> Option<String> {
        let wanted = fold(name);
        self.admitted(cap, basis)
            .into_iter()
            .find(|offer| {
                offer.tag.as_deref().is_some_and(|tag| fold(tag) == wanted)
                    || fold(&offer.provider) == wanted
            })
            .map(|offer| offer.tag.clone().unwrap_or_else(|| offer.provider.clone()))
    }

    /// The cheapest usable offer, whatever it costs.
    ///
    /// Used to explain a rung that was skipped: knowing the floor was $0.63
    /// when the ceiling was $0.30 is what makes the decision reviewable.
    #[must_use]
    pub fn floor(&self, basis: CostBasis) -> Option<f64> {
        self.offers
            .iter()
            .filter(|offer| offer.usable)
            .map(|offer| offer.price(basis))
            .min_by(|left, right| left.partial_cmp(right).unwrap_or(std::cmp::Ordering::Equal))
    }

    /// The smallest discount off the direct price that still admits an offer
    /// under `cap`, as a whole percentage.
    ///
    /// Surplus filters by discount rather than by absolute price, so a dollar
    /// ceiling has to be restated in those terms. Returns `None` when no offer
    /// publishes a direct price to discount against.
    ///
    /// The comparison is always against the direct *output* price, because that
    /// is the only undiscounted figure the marketplace publishes; the ladder's
    /// cost basis does not apply here.
    #[must_use]
    pub fn discount_floor_pct(&self, cap: f64) -> Option<u8> {
        let direct = self
            .offers
            .iter()
            .filter_map(|offer| offer.direct_completion_per_1m)
            .find(|direct| *direct > 0.0)?;

        let ratio = (cap / direct).clamp(0.0, 1.0);
        let target = (1.0 - ratio) * 100.0;

        // The largest whole percentage the ceiling justifies. Searching down
        // from 99 rounds toward the looser filter, so the discount asked for is
        // never more than the ceiling implies and never excludes an offer that
        // fits. Surplus rejects everything at 100, which would make an
        // affordable rung unreachable, so 99 is the tightest usable filter.
        Some(
            (0..=99_u8)
                .rev()
                .find(|candidate| f64::from(*candidate) <= target)
                .unwrap_or(0),
        )
    }
}

/// Folds a sub-provider name for comparison across the two vocabularies.
fn fold(name: &str) -> String {
    name.to_ascii_lowercase()
        .chars()
        .filter(|character| !character.is_whitespace())
        .collect()
}

//! The price table the selection engine reads.
//!
//! Marketplace payloads are parsed into [`Offer`]s by each provider module;
//! this module only stores the result and answers questions about it. Keeping
//! the store free of I/O is what lets the selection engine be tested without a
//! network.

mod types;

pub use types::{ModelPrices, Offer};

use std::collections::BTreeMap;

/// A snapshot of every model's offers, keyed by provider name and model slug.
#[derive(Debug, Default, Clone)]
pub struct PriceTable {
    entries: BTreeMap<(String, String), ModelPrices>,
}

impl PriceTable {
    /// An empty table, as held before the first refresh completes.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Replaces one model's offers.
    pub fn insert(
        &mut self,
        provider: impl Into<String>,
        model: impl Into<String>,
        prices: ModelPrices,
    ) {
        self.entries.insert((provider.into(), model.into()), prices);
    }

    /// The offers held for one model, if any refresh has succeeded for it.
    #[must_use]
    pub fn get(&self, provider: &str, model: &str) -> Option<&ModelPrices> {
        // The tuple key means a lookup would otherwise have to allocate two
        // owned strings; searching the map directly avoids that on the hot
        // path, which runs once per rung per request.
        self.entries
            .iter()
            .find(|((entry_provider, entry_model), _)| {
                entry_provider == provider && entry_model == model
            })
            .map(|(_, prices)| prices)
    }

    /// How many models the table holds.
    #[must_use]
    pub fn len(&self) -> usize {
        self.entries.len()
    }

    /// Whether no refresh has landed yet.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }
}

